# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TEKNOLOJİ FELSEFESİ: TEKNOLOJİNİN DOĞASI VE YAKLAŞIMLAR</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tekhne\'den Teknolojiye</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• Antik Yunanca &quot;tekhne&quot;</text>\n  <text x="50" y="120" font-size="10.5" fill="#475569">(zanaat, beceri, yapıp etme</text>\n  <text x="50" y="137" font-size="10.5" fill="#475569">bilgisi) + &quot;logos&quot; kavramları.</text>\n  <text x="40" y="165" font-size="11" fill="#334155">• Bilimsel bilginin pratik</text>\n  <text x="50" y="182" font-size="10.5" fill="#475569">amaçlar ve insan ihtiyaçları</text>\n  <text x="50" y="199" font-size="10.5" fill="#475569">için araçlara dönüştürülmesi.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Araçsalcı (Tarafsız) Görüş</text>\n  <text x="262" y="103" font-size="11" fill="#334155">• Teknoloji kendi başına</text>\n  <text x="272" y="120" font-size="10.5" fill="#475569">ne iyidir ne de kötüdür;</text>\n  <text x="272" y="137" font-size="10.5" fill="#475569">değerden bağımsız bir araçtır.</text>\n  <text x="262" y="165" font-size="11" fill="#334155">• Onu iyi veya kötü yapan,</text>\n  <text x="272" y="182" font-size="10.5" fill="#475569">insanın kullanım niyeti ve</text>\n  <text x="272" y="199" font-size="10.5" fill="#166534" font-weight="bold">seçtiği amaçlardır.</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Özcü / Otonom Görüş</text>\n  <text x="485" y="103" font-size="11" fill="#334155">• Martin Heidegger ve Jacques</text>\n  <text x="495" y="120" font-size="10.5" fill="#475569">Ellul: Teknoloji salt bir araç</text>\n  <text x="495" y="137" font-size="10.5" fill="#475569">değil, dünyayı algılama ve</text>\n  <text x="495" y="154" font-size="10.5" fill="#475569">varoluş biçimidir.</text>\n  <text x="485" y="180" font-size="11" fill="#334155">• Doğayı salt &quot;kullanıma hazır</text>\n  <text x="495" y="197" font-size="10.5" fill="#b45309" font-weight="bold">rezerv (el-altında-varlık)&quot; görür.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TEKNOLOJİ BAĞLAMINDA AKSİYOLOJİK (DEĞER / ETİK) PROBLEMLER</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Dijital Etik, Mahremiyet ve Özgürlük</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">• Kişisel verilerin izlenmesi ve mahremiyetin</text>\n  <text x="62" y="123" font-size="11" fill="#475569">(özel yaşamın gizliliğinin) aşınması</text>\n  <text x="50" y="148" font-size="11.5" fill="#334155">• Algoritmik yönlendirme ve yankı odalarının</text>\n  <text x="62" y="166" font-size="11" fill="#475569">bireyin özgür iradesini sınırlandırması</text>\n  <text x="50" y="191" font-size="11.5" fill="#334155">• Dijital yabancılaşma, yalnızlaşma ve</text>\n  <text x="62" y="209" font-size="11" fill="#475569">hakikat sonrası (post-truth) dezenformasyon</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Yapay Zekâ ve Biyoetik Sorunları</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• Otonom sistemlerin ve yapay zekânın aldığı</text>\n  <text x="392" y="123" font-size="11" fill="#475569">kararlarda ahlaki ve hukuki sorumluluk kimdedir?</text>\n  <text x="380" y="148" font-size="11.5" fill="#334155">• Biyoteknoloji, gen düzenleme ve klonlama</text>\n  <text x="392" y="166" font-size="11" fill="#475569">uygulamalarında insan onurunun korunması</text>\n  <text x="380" y="191" font-size="11.5" fill="#334155">• Transhümanizm tartışmaları ve teknolojik</text>\n  <text x="392" y="209" font-size="11" fill="#475569">eşitsizlik (dijital uçurum) problemi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HANS JONAS: SORUMLULUK İLKESİ VE TEKNOLOJİ ETİĞİ</text>\n  <rect x="35" y="55" width="300" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Geleneksel Etikten Gelecek Etiğine</text>\n  <text x="50" y="110" font-size="11.5" fill="#334155">• Geleneksel etik yalnızca &quot;şimdi ve burada&quot;</text>\n  <text x="62" y="128" font-size="11" fill="#475569">yaşayan insanlar arası ilişkileri düzenliyordu.</text>\n  <text x="50" y="155" font-size="11.5" fill="#334155">• Modern teknoloji ise küresel ekosistemi ve</text>\n  <text x="62" y="173" font-size="11" fill="#475569">henüz doğmamış gelecek kuşakların varlığını</text>\n  <text x="62" y="191" font-size="11" fill="#475569">geri dönülmez biçimde etkileme gücüne sahiptir.</text>\n  <rect x="365" y="55" width="300" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Hans Jonas\'ın Ekolojik Buyruğu</text>\n  <text x="380" y="110" font-size="11.5" font-weight="bold" fill="#b45309">&quot;Öyle hareket et ki, eylemlerinin sonuçları</text>\n  <text x="380" y="130" font-size="11.5" font-weight="bold" fill="#b45309">yeryüzünde gerçek insan yaşamının</text>\n  <text x="380" y="150" font-size="11.5" font-weight="bold" fill="#b45309">sürekliliği ile bağdaşabilsin!&quot;</text>\n  <text x="380" y="182" font-size="11" fill="#334155">• İhtiyat ilkesi, insan onuru ve sürdürülebilir</text>\n  <text x="392" y="200" font-size="11" fill="#334155">teknoloji kullanımı temel değer ölçütüdür.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
